def numSubarrayBoundedMax(nums, left, right):
    # Helper to count subarrays where max element ≤ bound
    def count(bound):
        res = 0
        curr = 0
        for num in nums:
            if num <= bound:
                curr += 1    # extend valid subarrays ending here
            else:
                curr = 0     # reset at any number > bound
            res += curr
        return res

    return count(right) - count(left - 1)
